const body = $json.body ?? $json;
const required = ['user','department','requested_role','resource'];
const missing = required.filter(k => !body[k]);
if (missing.length) {
  return [{ json: { valid: false, status: 'DENIED', reason: `Missing fields: ${missing.join(', ')}`, request: body } }];
}
return [{ json: { valid: true, request: body } }];

const input = $json.request;
if (!$json.valid) return [{ json: $json }];

const policies = {
  developer: ['github-repository', 'staging-environment'],
  analyst: ['analytics-dashboard'],
  viewer: ['documentation']
};

const allowedResources = policies[input.requested_role] || [];
const approved = allowedResources.includes(input.resource);

return [{
  json: {
    ...$json,
    role: input.requested_role,
    allowedResources,
    approved,
    status: approved ? 'APPROVED' : 'DENIED',
    reason: approved ? 'Role is permitted to access requested resource.' : 'Role is not permitted to access requested resource.'
  }
}];

const r = $json.request || {};
const audit = {
  timestamp: new Date().toISOString(),
  user: r.user,
  department: r.department,
  role: r.requested_role,
  resource: r.resource,
  decision: $json.status,
  reason: $json.reason
};
return [{ json: { ...$json, audit } }];
